import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x111);
    address bob = address(0x222);

    function setUp() public { 
        c = new C(); 
        c.SetMinSum(1e18);
        c.SetLogFile(address(0xdead));
        c.Initialized();
    }

    function testFuzz_property(uint256 amountAlice, uint256 amountBob, uint256 collectAm) public {
        // Bound amounts to avoid overflow and ensure reasonable values
        amountAlice = bound(amountAlice, 0, 1e18);
        amountBob = bound(amountBob, 0, 1e18);
        collectAm = bound(collectAm, 0, 1e18);

        // Give initial balances
        vm.deal(alice, amountAlice);
        vm.deal(bob, amountBob);

        // Deposit for both
        vm.prank(alice);
        c.Deposit{value: amountAlice}();

        vm.prank(bob);
        c.Deposit{value: amountBob}();

        // Record balances before collect
        uint256 aliceBalanceBefore = c.balances(alice);
        uint256 bobBalanceBefore = c.balances(bob);
        uint256 sumBefore = aliceBalanceBefore + bobBalanceBefore;

        // Alice tries to collect
        vm.prank(alice);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAm));

        // If successful, check invariant
        if (success) {
            uint256 aliceBalanceAfter = c.balances(alice);
            uint256 bobBalanceAfter = c.balances(bob);
            uint256 sumAfter = aliceBalanceAfter + bobBalanceAfter;
            assertTrue(sumAfter <= sumBefore, "Sum of balances increased");
        }
    }
}

