pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 am, uint256 initialBalance, uint256 depositAmount) public {
        // Bound inputs to avoid overflow or reverts from the Deposit check
        vm.assume(caller != address(0));
        am = bound(am, 0, 1e30);
        minSum = bound(minSum, 0, 1e30);
        depositAmount = bound(depositAmount, 0, 1e28);
        initialBalance = bound(initialBalance, 0, 1e30);

        // Set MinSum and initialize contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund the caller with some ETH for deposit and other potential sends
        vm.deal(caller, initialBalance + depositAmount + am);

        // Deposit funds so the caller has a balance
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);
        bool shouldDecrease = (balanceBefore >= minSum && balanceBefore >= am);

        // Call Collect
        vm.prank(caller);
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));

        uint256 balanceAfter = c.balances(caller);

        // Rule: If condition held, balance decreases by am; otherwise, balance unchanged
        if (success) {
            if (shouldDecrease) {
                assertTrue(balanceAfter == balanceBefore - am, "Balance should decrease by am when condition met");
            } else {
                assertTrue(balanceAfter == balanceBefore, "Balance should remain unchanged when condition not met");
            }
        } else {
            // If reverted, balance must be unchanged
            assertTrue(balanceAfter == balanceBefore, "Balance unchanged on revert");
        }
    }
}

