            // user's balance decreased by collectAmount, contract balance decreased by collectAmount
            uint256 expectedContractBalance = balanceBefore - collectAmount;
            uint256 actualContractBalance = address(c).balance;
            assertTrue(actualContractBalance == expectedContractBalance, "Contract balance invariant broken");
