pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to reasonable values
        minSum = bound(minSum, 0, 1e18);
        depositAmount = bound(depositAmount, 0, 1e18);
        collectAmount = bound(collectAmount, 0, 1e18);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit funds for caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Store balance before collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Get balance after collect
        uint256 balanceAfter = c.balances(caller);

        // General rule: The only mutation is that M adds instead of subtracts.
        // In the reference (P), if Collect succeeds (balanceBefore >= minSum && balanceBefore >= collectAmount && internal call succeeds),
        // then balanceAfter = balanceBefore - collectAmount.
        // If Collect reverts or condition fails, balanceAfter == balanceBefore.
        // The rule: balanceAfter <= balanceBefore (never increases).
        // The mutant breaks this because Collect can increase the balance.
        assertTrue(balanceAfter <= balanceBefore, "Balance should never increase after Collect");
    }
}

