pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[2] memory addrs, uint256[2] memory deposits, uint256 collectAmt) public {
        vm.assume(addrs[0] != address(0) && addrs[1] != address(0) && addrs[0] != addrs[1]);
        vm.assume(deposits[0] > 0 && deposits[1] > 0);
        vm.assume(collectAmt > 0 && collectAmt <= deposits[0] + deposits[1]);
        // Set MinSum to allow collection
        c.SetMinSum(1e10);
        c.Initialized();
        // Fund accounts for deposit
        vm.deal(addrs[0], deposits[0]);
        vm.deal(addrs[1], deposits[1]);
        // Both deposit
        vm.prank(addrs[0]);
        c.Deposit{value: deposits[0]}();
        vm.prank(addrs[1]);
        c.Deposit{value: deposits[1]}();
        // Record total before Collect
        uint256 totalBefore = c.balances(addrs[0]) + c.balances(addrs[1]);
        // Caller = addrs[0], collect amount
        vm.prank(addrs[0]);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmt));
        if (success) {
            // If Collect succeeded, total should remain same (only transfer, not burn)
            uint256 totalAfter = c.balances(addrs[0]) + c.balances(addrs[1]);
            assertTrue(totalAfter == totalBefore, "Total balances should stay same after successful Collect");
        } else {
            // If Collect reverted, total unchanged
            uint256 totalAfter = c.balances(addrs[0]) + c.balances(addrs[1]);
            assertTrue(totalAfter == totalBefore, "Total balances should stay same after reverted Collect");
        }
    }
}

