pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[2] memory addr, uint256[2] memory _bal, uint256 _am) public {
        _am = bound(_am, 0, 1e18);
        for (uint i = 0; i < 2; i++) {
            _bal[i] = bound(_bal[i], 0, 1e18);
            if (addr[i] != address(0)) {
                vm.deal(addr[i], _bal[i]);
                vm.prank(addr[i]);
                c.Deposit{value: _bal[i]}();
            }
        }
        // Ensure MinSum is 0 so Collect can succeed
        c.SetMinSum(0);
        c.Initialized();

        uint sumBefore = 0;
        for (uint i = 0; i < 2; i++) {
            if (addr[i] != address(0)) {
                sumBefore += c.balances(addr[i]);
            }
        }

        // Call Collect from a random address that has sufficient balance
        address caller = addr[0] != address(0) ? addr[0] : addr[1];
        if (caller == address(0)) return;
        uint callerBal = c.balances(caller);
        if (callerBal < _am) return;

        vm.prank(caller);
        c.Collect(_am);

        uint sumAfter = 0;
        for (uint i = 0; i < 2; i++) {
            if (addr[i] != address(0)) {
                sumAfter += c.balances(addr[i]);
            }
        }

        assertTrue(sumAfter <= sumBefore + _am, "Total sum increased after Collect");
    }
}

