import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _minSum, uint256 _deposit, uint256 _collectAm) public {
        // Bound inputs to avoid overflow/revert
        _deposit = bound(_deposit, 1, 1e30);
        _collectAm = bound(_collectAm, 0, _deposit);

        // Try to set MinSum (if called before initialization)
        vm.assume(_minSum <= 1e30);
        c.SetMinSum(_minSum);

        // Initialize the contract (after this, SetMinSum reverts)
        c.Initialized();

        // Fund the test contract for deposit
        vm.deal(address(this), _deposit);
        c.Deposit{value: _deposit}();

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Call Collect
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _collectAm));
        if (ok) {
            // After Collect, MinSum must be unchanged (still = minSumBefore)
            assertTrue(c.MinSum() == minSumBefore);
        } else {
            // If Collect reverted, MinSum must still equal the value set before init (default 0 if never set)
            assertTrue(c.MinSum() == minSumBefore);
        }
    }
}

