    function testFuzz_property(uint256 val1, uint256 val2) public {
        vm.assume(val1 != val2);
        // Initialize MinSum to val1
        c.SetMinSum(val1);
        // Initialize the contract (calls Initialized, which sets the flag)
        c.Initialized();
        // Now try to set MinSum again to val2 via SetMinSum (should revert if intitalized flag is set)
        // But Collect will check balances[msg.sender] >= MinSum && balances[msg.sender] >= _am
        // We need to deposit first to have enough balance
        vm.deal(address(this), 1 ether);
        // Deposit some amount that is >= val1 and val2
        c.Deposit{value: val1 + val2}();
        // Now try to Collect an amount that is at least val1
        // The call to Collect will revert if MinSum > balances[msg.sender], but we have enough
        // We only care whether MinSum changed after Initialized
        // The Collect function does not change MinSum, but we can observe MinSum value
        // Actually the property: after Initialized, MinSum must stay at val1
        // We can call SetMinSum again (it will revert in reference, but not in mutant)
        // So we check that after a second SetMinSum call, MinSum is unchanged
        // However SetMinSum might revert, so we need to catch revert
        // Simpler: just observe that MinSum remains val1 after a second SetMinSum call
        c.SetMinSum(val2); // In reference, this reverts; in mutant, it does not
        // If no revert (mutant), MinSum changed; if revert (reference), MinSum stayed
        // But we cannot distinguish revert here. Instead, check directly:
        uint256 currentMinSum = c.MinSum();
        assertTrue(currentMinSum == val1, "MinSum should not change after initialization");
    }
}

