        depositAmount = bound(depositAmount, 1, 1e24);
        collectAmount = bound(collectAmount, 0, depositAmount);

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Set MinSum to 0 so Collect can succeed
        vm.prank(address(0)); // arbitrary prank to avoid initial check
        // Actually we need to call SetMinSum and Initialized
