import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr1, address addr2, uint256 val1, uint256 val2, uint256 collectAmt) public {
        // Ensure addresses are different and valid
        vm.assume(addr1 != address(0) && addr2 != address(0));
        vm.assume(addr1 != addr2);
        // Bound deposit amounts to avoid overflow (max 1e10 ether in wei)
        val1 = bound(val1, 1, 1e28);
        val2 = bound(val2, 1, 1e28);
        collectAmt = bound(collectAmt, 0, val1 + val2);

        // Initialize and set MinSum to 0 so that Collect can work
        c.SetMinSum(0);
        c.Initialized();

        // Prepare balances: deposit from addr1 and addr2
        vm.deal(addr1, val1);
        vm.prank(addr1);
        c.Deposit{value: val1}();

        uint256 balanceBeforeCollect = address(c).balance;

        vm.deal(addr2, val2);
        vm.prank(addr2);
        c.Deposit{value: val2}();

        uint256 balanceAfterDeposits = address(c).balance;
        // balanceAfterDeposits should be val1 + val2 in reference, but in bug it's val1 + val2 (no change yet)

        // Now call Collect from addr1 with collectAmt
        vm.prank(addr1);
        (bool successCollect, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        uint256 balanceAfterCollect = address(c).balance;

        // Sum all balances in mapping (only addr1 and addr2 matter here)
        uint256 bal1 = c.balances(addr1);
        uint256 bal2 = c.balances(addr2);
        uint256 sumMapped = bal1 + bal2;

        // The invariant: after deposits and a Collect call, the sum of mapped balances plus the contract's ether balance is non-increasing compared to before deposits? No.
        // Actually, a valid rule: After any sequence that ends with a Collect call, the sum of mapped balances never exceeds the total ether ever deposited minus the amount successfully collected.
        // Since we can't track total deposited directly, we observe that mapped sum + contract balance == total deposited (if no collects succeeded, else contract balance decreases by collected amount).
        // For reference: totalDeposited = val1 + val2; after Collect, contract balance = val1+val2 - collectedAmount (if success) or unchanged (if revert).
        // Since we can't see collected amount from public getters, we assert that mapped sum + contract balance == val1+val2 (total deposited).
        // This holds for reference because balances reflect net deposits minus collects, and contract balance reflects remaining ether.
        // For bug, balances decrease on deposit, so sumMapped will be less than actual deposits, breaking the relation.

        assertTrue(sumMapped + balanceAfterCollect == val1 + val2, "Invariant violation: mapped sum + contract balance != total deposited");
    }
}

