import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint amount, uint minSum, uint depositAmount, address other) public {
        vm.assume(caller != address(0));
        vm.assume(other != address(0));
        vm.assume(caller != other);
        vm.assume(amount <= type(uint256).max / 2);
        vm.assume(depositAmount <= type(uint256).max / 2);
        vm.assume(minSum <= type(uint256).max / 2);

        // Set up: minSum must be <= depositAmount for Collect to succeed
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund the caller with enough ether
        vm.deal(caller, depositAmount + amount);
        vm.deal(other, 1 ether);

        // Deposit from caller
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balances before Collect
        uint callerBalBefore = caller.balance;
        uint otherBalBefore = other.balance;
        uint contractBalBefore = address(c).balance;

        // Attempt Collect from caller
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));

        if (success) {
            // If Collect succeeded, the contract should have transferred `amount` ether to caller
            uint callerBalAfter = caller.balance;
            uint otherBalAfter = other.balance;
            uint contractBalAfter = address(c).balance;
            // General rule: caller's balance increased by amount, other balances unchanged, contract decreased by amount
            bool rule = (callerBalAfter == callerBalBefore + amount) &&
                        (otherBalAfter == otherBalBefore) &&
                        (contractBalAfter == contractBalBefore - amount);
            assertTrue(rule, "Collect success should transfer ether correctly");
        } else {
            // If Collect reverted, balances should be unchanged
            uint callerBalAfter = caller.balance;
            uint otherBalAfter = other.balance;
            uint contractBalAfter = address(c).balance;
            bool rule = (callerBalAfter == callerBalBefore) &&
                        (otherBalAfter == otherBalBefore) &&
                        (contractBalAfter == contractBalBefore);
            assertTrue(rule, "Collect revert should not change balances");
        }
    }
}

